from __future__ import annotations

import logging
from pathlib import Path
from typing import Any, Callable

ProgressCb = Callable[[dict[str, Any]], None]
CueCb = Callable[[dict[str, Any]], None]

from .island_workspace import (
    cleanup_island_workdir,
    make_island_workdir,
    raise_if_island_cancelled,
)
from .cue_align import (
    align_text_cues_to_timing,
)
from .cue_retime import (
    ensure_readable_cue_timings,
    repair_collapsed_asr_cues,
)
from .speech_spans import (
    _ANIME_VAD_CHUNK_THRESHOLD_S,
    _ANIME_VAD_MAX_GROUP_S,
    _ANIME_VAD_MERGE_GAP_S,
    _ANIME_VAD_MIN_ISLAND_S,
    _anime_ten_beam_size,
    _clamp_cues_to_span,
    _resolve_island_vad_backend,
    group_vad_intervals,
    nudge_cue_starts_past_silence,
    paint_text_onto_speech_spans,
    pcm_speech_intervals,
    refine_demucs_vad_intervals,
)
from .whisper_model_cache import (
    _get_cached_whisper_model,
)
from .whisper_segments import (
    _cues_from_whisper_segments,
)
from .qwen3_cues import (
    _dedupe_overlap_cues,
)

from .whisper_windows import (
    _shift_cues,
)
from ..device import is_cublas_missing_error
from ..progress import asr_local_from_timeline, format_mmss

_log = logging.getLogger("transub_engine.asr.whisper_anime_island")

def _whisper_anime_ten_island_transcribe(
    *,
    media_path: str,
    language: str,
    asr_model: str,
    device: str,
    beam_size: int,
    vad_options: dict[str, Any] | None,
    initial_prompt: str | None,
    hotwords: str | None,
    on_progress: ProgressCb | None,
    on_cue: CueCb | None,
    should_cancel: Callable[[], bool] | None,
    include_words: bool,
    duration_s: float,
    timing_align_model: str | None = None,
    vad_media_path: str | None = None,
) -> list[dict[str, Any]] | None:
    """
    anime-whisper island VAD path: TEN or FireRed frames -> anime-whisper text.

    VAD islands gate which audio is decoded (soft-AV recall). Cue bounds prefer
    PCM speech-active subspans inside each frame (skip pad/silence), then
    char-proportional paint. Intra-frame splits are still synthetic when the
    island is one continuous utterance.

    Performance: reuse the float32 PCM from VAD decode and feed ndarray
    slices to the cached WhisperModel (no per-frame ffmpeg trim).

    ``vad_media_path`` (optional): Demucs vocals for VAD; ASR PCM from
    ``media_path`` when they differ (enhance-for-VAD-only).
    """
    from ..device import resolve_ctranslate2_device
    from ..download import is_model_installed, model_local_path
    from ..vad.ten_vad_seg import asr_pcm_for_vad_intervals

    media_name = Path(media_path).name
    vad_path = str(vad_media_path or "").strip() or media_path
    vad_name = Path(vad_path).name
    island_backend = _resolve_island_vad_backend(timing_align_model) or "ten"
    intervals: list[tuple[float, float]] | None = None
    audio_f32 = None
    TEN_SR = 16000
    slice_pcm_f32 = None  # set below
    max_media = duration_s if duration_s > 0 else None

    if island_backend == "firered":
        from ..vad.firered_vad_seg import (
            collect_firered_vad_intervals_with_audio,
            firered_vad_available,
            firered_weights_dir,
        )
        from ..vad.ten_vad_seg import SAMPLE_RATE as TEN_SR, slice_pcm_f32

        if not firered_vad_available() or firered_weights_dir() is None:
            _log.info(
                "anime-whisper FireRed path skipped: fireredvad/weights missing | "
                "%s -> TEN/windowed fallback",
                vad_name,
            )
            island_backend = "ten"
        else:
            _log.info(
                "anime-whisper FireRed path start: %s | model=%s | duration=%.1fs | "
                "VAD owns timeline (knobs from job vad options)",
                vad_name,
                asr_model,
                float(duration_s or 0),
            )
            try:
                from ..runtime_extras import ensure_extras_for_models

                ensure_extras_for_models(
                    ["firered-vad"],
                    force=False,
                    on_progress=on_progress,
                )
                intervals, audio_f32 = collect_firered_vad_intervals_with_audio(
                    vad_path,
                    max_media_s=max_media,
                    vad_options=vad_options,
                    device=device,
                )
                try:
                    from ..vad.firered_vad_seg import clear_firered_vad_cache

                    clear_firered_vad_cache()
                except Exception:
                    pass
            except Exception as err:
                _log.warning(
                    "FireRed VAD island collect failed for %s: %s -> TEN/windowed fallback",
                    vad_name,
                    err,
                )
                island_backend = "ten"
                intervals = None
                audio_f32 = None
            if island_backend == "firered" and not intervals:
                _log.info(
                    "FireRed VAD found no speech islands on %s; falling back",
                    vad_name,
                )
                return None

    if island_backend == "ten":
        from ..vad.ten_vad_seg import (
            SAMPLE_RATE as TEN_SR,
            collect_ten_vad_intervals_with_audio,
            slice_pcm_f32,
            ten_vad_available,
        )

        if not ten_vad_available():
            _log.info(
                "anime-whisper TEN path skipped: ten-vad not installed | %s -> windowed/CPS fallback",
                vad_name,
            )
            return None

        _log.info(
            "anime-whisper TEN path start: %s | model=%s | duration=%.1fs | "
            "chunk_gap=%.2fs | max_frame=%.1fs (VAD owns timeline)",
            vad_name,
            asr_model,
            float(duration_s or 0),
            _ANIME_VAD_CHUNK_THRESHOLD_S,
            _ANIME_VAD_MAX_GROUP_S,
        )
        try:
            from ..vad.ten_vad_seg import (
                collect_ten_vad_intervals_with_audio,
                resolve_ten_params,
            )

            tp = resolve_ten_params(vad_options)
            merge_gap = float(tp["merge_gap_s"])
            threshold = float(tp["threshold"])
            min_speech_s = max(_ANIME_VAD_MIN_ISLAND_S, float(tp["min_speech_s"]))
            pad_s = float(tp["pad_s"])
            if (
                not isinstance(vad_options, dict)
                or (
                    vad_options.get("minSilenceMs") is None
                    and vad_options.get("min_silence_duration_ms") is None
                )
            ):
                merge_gap = _ANIME_VAD_MERGE_GAP_S
            # Demucs→VAD-only: floor soft-AV UI threshold/merge so TEN does not
            # glue 30s mega-islands that silence-split then bisect turns.
            if vad_path != media_path:
                _ten_default = resolve_ten_params(None)
                merge_gap = max(float(merge_gap), float(_ANIME_VAD_MERGE_GAP_S))
                threshold = max(float(threshold), float(_ten_default["threshold"]))
                min_speech_s = max(
                    float(min_speech_s), float(_ten_default["min_speech_s"])
                )
            intervals, audio_f32 = collect_ten_vad_intervals_with_audio(
                vad_path,
                max_media_s=max_media,
                threshold=threshold,
                min_speech_s=min_speech_s,
                merge_gap_s=merge_gap,
                pad_s=pad_s,
            )
        except Exception as err:
            _log.warning(
                "TEN VAD island collect failed for %s: %s -> windowed/CPS fallback",
                vad_name,
                err,
            )
            return None
        if not intervals:
            _log.info(
                "TEN VAD found no speech islands on %s; falling back to windowed ASR",
                vad_name,
            )
            return None

    if not intervals:
        return None

    audio_f32 = asr_pcm_for_vad_intervals(
        media_path,
        vad_media_path=vad_path if vad_path != media_path else None,
        vad_pcm=audio_f32,
        max_media_s=max_media,
    )
    # Desktop QC waveform: persist mix PCM after VAD→ASR path resolution.
    try:
        from ..audio.timing_pcm_cache import write_mix_timing_pcm

        write_mix_timing_pcm(audio_f32)
    except Exception as err:
        _log.debug("timing PCM cache skipped: %s", err)

    # FireRed soft-AV preset: align island grouping with resolved max speech / silence.
    group_gap = _ANIME_VAD_CHUNK_THRESHOLD_S
    group_max = _ANIME_VAD_MAX_GROUP_S
    if island_backend == "firered":
        try:
            from ..vad.firered_vad_seg import resolve_firered_params

            frp = resolve_firered_params(vad_options)
            group_gap = max(0.25, min(0.6, float(frp["merge_gap_s"])))
            group_max = max(3.5, min(7.5, float(frp["max_speech_s"])))
        except Exception:
            group_gap = 0.35
            group_max = 7.0

    # Demucs→VAD-only: re-split mega-islands on the ASR mix (soft-AV pauses).
    if vad_path != media_path and intervals:
        try:
            before_n = len(intervals)
            intervals = refine_demucs_vad_intervals(
                intervals,
                audio_f32,
                TEN_SR,
                long_island_s=10.0,
                min_silence_s=0.48,
            )
            if len(intervals) != before_n:
                _log.info(
                    "anime-whisper Demucs-VAD refine: %d→%d intervals on %s",
                    before_n,
                    len(intervals),
                    media_name,
                )
            # Keep Demucs silence-split gaps as separate ASR frames (≥0.4s pauses).
            # Wider max group avoids hard-chopping 8–9s intro clusters.
            group_gap = min(group_gap, 0.32)
            group_max = max(group_max, 9.5)
        except Exception as err:
            _log.debug("anime-whisper Demucs island refine skipped: %s", err)

    pieces = group_vad_intervals(
        intervals,
        chunk_threshold_s=group_gap,
        max_group_duration_s=group_max,
    )
    if not pieces:
        _log.info(
            "TEN VAD grouping produced 0 frames on %s; falling back to windowed ASR",
            media_name,
        )
        return None

    spoken = sum(max(0.0, e - s) for s, e in pieces)
    max_span = max((e - s) for s, e in pieces) if pieces else 0.0
    _log.info(
        "anime-whisper TEN frames: %s | islands=%d -> frames=%d | spoken=%.1fs | "
        "max_frame=%.2fs | first=%.1f-%.1fs | last=%.1f-%.1fs",
        media_name,
        len(intervals),
        len(pieces),
        spoken,
        max_span,
        pieces[0][0],
        pieces[0][1],
        pieces[-1][0],
        pieces[-1][1],
    )

    if not is_model_installed(asr_model):
        _log.warning("anime-whisper TEN path: model not installed: %s", asr_model)
        return None

    try:
        from .whisper_av_shim import import_whisper_model_class

        WhisperModel, _used_ffmpeg_audio = import_whisper_model_class()
    except Exception as err:
        _log.warning("anime-whisper TEN path: cannot load Whisper class: %s", err)
        return None

    try:
        from ..runtime_gpu import inject_nvidia_lib_path

        inject_nvidia_lib_path()
    except Exception:
        pass

    requested = str(device or "auto").strip().lower()
    dev = resolve_ctranslate2_device(requested)
    compute = "float16" if dev == "cuda" else "int8"
    # ChronosJAV / litagin anime-whisper: greedy only. Short VAD islands gain
    # little from beam search and pay 15–40% wall time. Whisper JA keeps beam.
    from ..models_catalog import asr_is_anime_whisper

    requested_beam = max(1, min(20, int(beam_size or 1)))
    if asr_is_anime_whisper(asr_model):
        beam = _anime_ten_beam_size(beam_size)
    else:
        beam = requested_beam
    model_dir = str(model_local_path(asr_model))
    model = _get_cached_whisper_model(
        WhisperModel,
        model_dir,
        device=dev,
        compute_type=compute,
    )
    lang = None if not language or language == "auto" else language
    use_word_ts = bool(include_words)

    transcribe_kw: dict[str, Any] = {
        "language": lang,
        "beam_size": beam,
        "word_timestamps": use_word_ts,
        "condition_on_previous_text": False,
        "suppress_blank": True,
        "vad_filter": False,
        # Island already isolates speech; keep quiet dialogue.
        "no_speech_threshold": 0.95,
        "log_prob_threshold": -1.6,
        "compression_ratio_threshold": 2.6,
    }
    prompt = str(initial_prompt or "").strip()
    words = str(hotwords or "").strip()
    # anime-whisper: prompts cause hallucinations — normally cleared upstream.
    if prompt:
        transcribe_kw["initial_prompt"] = prompt[:800]
    if words:
        transcribe_kw["hotwords"] = words[:400]

    if asr_is_anime_whisper(asr_model) and requested_beam != 1:
        _log.info(
            "anime-whisper island ASR: beam_size forced to 1 (greedy); request had %d",
            requested_beam,
        )
    _log.info(
        "whisper island ASR: in-memory PCM slices | model=%s | device=%s | beam=%d | frames=%d",
        asr_model,
        dev,
        beam,
        len(pieces),
    )

    all_cues: list[dict[str, Any]] = []
    empty_frames = 0
    slice_fails = 0
    ffmpeg_fallback = 0
    log_every = max(1, len(pieces) // 20)
    work: Path | None = None

    def _transcribe_audio(audio_in: Any) -> list[dict[str, Any]]:
        try:
            segments, _info = model.transcribe(audio_in, **transcribe_kw)
        except TypeError:
            kw = dict(transcribe_kw)
            for drop in ("hotwords", "initial_prompt", "hallucination_silence_threshold"):
                kw.pop(drop, None)
            try:
                segments, _info = model.transcribe(audio_in, **kw)
            except TypeError:
                kw.pop("clip_timestamps", None)
                segments, _info = model.transcribe(audio_in, **kw)
        return _cues_from_whisper_segments(segments, include_words=include_words)

    def _ffmpeg_fallback_frame(start: float, end: float, idx: int) -> list[dict[str, Any]]:
        nonlocal work, ffmpeg_fallback
        from ..audio.preprocess import trim_media_window

        if work is None:
            work = make_island_workdir("aw_ten_isle_")
        wav = trim_media_window(
            media_path,
            start_sec=start,
            end_sec=end,
            out_dir=work / f"i{idx:04d}",
        )
        ffmpeg_fallback += 1
        return _transcribe_audio(wav)

    try:
        if on_progress:
            vad_label = "FireRed" if island_backend == "firered" else "TEN"
            on_progress(
                {
                    "stage": "transcribe",
                    "percent": 12,
                    "detail": f"{vad_label} 人声帧 {len(pieces)} 段 | 逐段 {asr_model}",
                    "processedSec": 0.0,
                    "mediaDurationSec": duration_s if duration_s > 0 else None,
                }
            )
        for i, (start, end) in enumerate(pieces):
            raise_if_island_cancelled(should_cancel)
            span = max(0.0, end - start)
            if span < _ANIME_VAD_MIN_ISLAND_S:
                continue
            if on_progress:
                local_pct = asr_local_from_timeline(
                    processed_s=start,
                    duration_s=duration_s if duration_s > 0 else max(end, 1.0),
                    start=15.0,
                    end=92.0,
                )
                detail = f"帧 {i + 1}/{len(pieces)}"
                if duration_s > 0:
                    detail = (
                        f"{format_mmss(start)} / {format_mmss(duration_s)} | "
                        f"帧 {i + 1}/{len(pieces)}"
                    )
                on_progress(
                    {
                        "stage": "transcribe",
                        "percent": int(local_pct),
                        "detail": detail,
                        "processedSec": float(start),
                        "mediaDurationSec": duration_s if duration_s > 0 else None,
                    }
                )
            if i == 0 or i + 1 == len(pieces) or (i + 1) % log_every == 0:
                _log.info(
                    "anime-whisper TEN frame %d/%d: %.2f-%.2fs (%.2fs)",
                    i + 1,
                    len(pieces),
                    start,
                    end,
                    span,
                )

            part: list[dict[str, Any]] = []
            frame_pcm: Any = None
            try:
                clip = slice_pcm_f32(audio_f32, start, end, sample_rate=TEN_SR)
                if clip.size < int(0.05 * TEN_SR):
                    raise RuntimeError("PCM slice too short")
                frame_pcm = clip
                part = _transcribe_audio(clip)
            except Exception as err:
                slice_fails += 1
                # CUDA selected but cuBLAS unloadable: switch whole TEN pass to CPU
                # once. Per-frame ffmpeg trim on a dead CUDA model is extremely slow
                # (thousands of frames) and still fails the same DLL error.
                if (
                    dev == "cuda"
                    and is_cublas_missing_error(err)
                    and "cublas" in str(err or "").lower()
                ):
                    _log.warning(
                        "TEN ASR CUDA cuBLAS failed on frame %d/%d (%s); "
                        "reloading Whisper on CPU for remaining frames",
                        i + 1,
                        len(pieces),
                        err,
                    )
                    if on_progress:
                        on_progress(
                            {
                                "stage": "model",
                                "percent": max(12, int(local_pct)),
                                "detail": "CUDA cuBLAS 不可用，改用 CPU 继续…",
                            }
                        )
                    dev = "cpu"
                    compute = "int8"
                    model = _get_cached_whisper_model(
                        WhisperModel,
                        model_dir,
                        device=dev,
                        compute_type=compute,
                    )
                    try:
                        clip = slice_pcm_f32(audio_f32, start, end, sample_rate=TEN_SR)
                        frame_pcm = clip
                        part = _transcribe_audio(clip)
                    except Exception as err_cpu:
                        _log.warning(
                            "TEN PCM slice ASR failed on CPU %s %.2f-%.2fs: %s; "
                            "trying ffmpeg trim",
                            media_name,
                            start,
                            end,
                            err_cpu,
                        )
                        try:
                            part = _ffmpeg_fallback_frame(start, end, i)
                        except Exception as err2:
                            _log.warning(
                                "TEN island ffmpeg fallback failed %s %.2f-%.2fs: %s",
                                media_name,
                                start,
                                end,
                                err2,
                            )
                            continue
                else:
                    _log.warning(
                        "TEN PCM slice ASR failed %s %.2f-%.2fs: %s; trying ffmpeg trim",
                        media_name,
                        start,
                        end,
                        err,
                    )
                    try:
                        part = _ffmpeg_fallback_frame(start, end, i)
                    except Exception as err2:
                        _log.warning(
                            "TEN island ffmpeg fallback failed %s %.2f-%.2fs: %s",
                            media_name,
                            start,
                            end,
                            err2,
                        )
                        continue

            texts = [
                str(c.get("text") or "").strip()
                for c in (part or [])
                if isinstance(c, dict) and str(c.get("text") or "").strip()
            ]
            if not texts:
                empty_frames += 1
                _log.debug(
                    "anime-whisper TEN frame %d/%d empty: %.2f-%.2fs",
                    i + 1,
                    len(pieces),
                    start,
                    end,
                )
                continue
            # Prefer PCM speech subspans so cues skip VAD pad / mid-island silence.
            joined = "".join(texts)
            speech_spans: list[tuple[float, float]] | None = None
            if frame_pcm is not None:
                try:
                    speech_spans = pcm_speech_intervals(
                        frame_pcm,
                        TEN_SR,
                        offset_s=0.0,
                    ) or None
                except Exception:
                    speech_spans = None
            local = paint_text_onto_speech_spans(
                joined,
                island_start=0.0,
                island_end=span,
                speech_spans=speech_spans,
            )
            if not local:
                local = repair_collapsed_asr_cues(part or [], media_end_s=span)
                if local and span > 0.25:
                    local = align_text_cues_to_timing(
                        local,
                        [{"start": 0.0, "end": span, "text": "speech"}],
                    )
            shifted = _clamp_cues_to_span(_shift_cues(local, start), start, end)
            if on_cue:
                for cue in shifted:
                    on_cue(cue)
            all_cues.extend(shifted)
            _log.debug(
                "anime-whisper TEN frame %d/%d -> %d cue(s): %s",
                i + 1,
                len(pieces),
                len(shifted),
                (joined[:48] + "...") if len(joined) > 48 else joined,
            )
    finally:
        cleanup_island_workdir(work)

    _log.info(
        "anime-whisper TEN path done: %s | decode_mode=pcm_reuse | frames=%d | "
        "cues=%d | empty=%d | slice_fail=%d | ffmpeg_fallback=%d",
        media_name,
        len(pieces),
        len(all_cues),
        empty_frames,
        slice_fails,
        ffmpeg_fallback,
    )
    # Empty list must not count as success — callers use truthiness to fall through
    # to fixed-window ASR (soft-AV mis-threshold VAD can yield frames with no text).
    if not all_cues:
        _log.info(
            "anime-whisper TEN path produced 0 cues for %s "
            "(frames=%d empty=%d slice_fail=%d); returning None for windowed fallback",
            media_name,
            len(pieces),
            empty_frames,
            slice_fails,
        )
        try:
            del audio_f32
        except Exception:
            pass
        return None
    try:
        all_cues = nudge_cue_starts_past_silence(all_cues, audio_f32, sample_rate=TEN_SR)
    except Exception:
        pass
    try:
        del audio_f32
    except Exception:
        pass
    try:
        all_cues = ensure_readable_cue_timings(
            all_cues,
            media_end_s=float(duration_s) if duration_s else None,
        )
    except Exception:
        pass
    if on_progress:
        on_progress(
            {
                "stage": "transcribe",
                "percent": 96,
                "detail": f"{len(all_cues)} 条（TEN 逐帧）",
                "processedSec": duration_s if duration_s > 0 else None,
                "mediaDurationSec": duration_s if duration_s > 0 else None,
            }
        )
    return _dedupe_overlap_cues(all_cues)
